SELECT  FROM devices
WHERE id IN
#{id}

SELECT , (SELECT a.agent_status FROM device_agents a WHERE a.device_id = devices.id) AS agent_status_view, (SELECT a.online_status FROM device_agents a WHERE a.device_id = devices.id) AS online_status_view FROM devices
device_status <> 'DELETED'
AND COALESCE((SELECT a.online_status FROM device_agents a WHERE a.device_id = devices.id), 'OFFLINE') = #{onlineStatus}
AND device_type_code = #{deviceTypeCode}
AND (device_name LIKE CONCAT('%', #{keyword}, '%') OR device_code LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY id
